module DE = Downwards_env
module T = Flambda2_types
open Port_monad

type t =
  { continuation_uses : Continuation_uses.t Continuation.Map.t;
    continuation_arities : [`Unarized] Flambda_arity.t Continuation.Map.t
  }

(** val continuation_uses : t -> Continuation_uses.t Continuation.Map.t **)

let continuation_uses t0 = t0.continuation_uses

(** val continuation_arities : t -> [ `Unarized ] Flambda_arity.t
    Continuation.Map.t **)

let continuation_arities t0 = t0.continuation_arities

(** val print : Format.formatter -> t -> unit coq_M **)

let print ppf t0 =
  let { continuation_uses = continuation_uses0;
        continuation_arities = continuation_arities0
      } =
    t0
  in
  Format.fprintf ppf
    "@[<hov 1>(@[<hov 1>(continuation_uses@ %a)@]@ @[<hov \
     1>(continuation_arities@ %a)@])@]"
    (Continuation.Map.print Continuation_uses.print)
    continuation_uses0
    (Continuation.Map.print Flambda_arity.print)
    continuation_arities0

(** val empty : t **)

let empty =
  { continuation_uses = Continuation.Map.empty;
    continuation_arities = Continuation.Map.empty
  }

(** val record_continuation : t -> Continuation.t -> [ `Unarized ]
    Flambda_arity.t -> t coq_M **)

let record_continuation t0 cont0 arity =
  let continuation_arities0 =
    Continuation.Map.update cont0
      (fun o ->
        match o with
        | Some _ ->
          Misc.fatal_errorf
            "[CUE.record_continuation]: continuation %a already present in \
             continuation_uses_env"
            Continuation.print cont0
        | None -> Some arity)
      t0.continuation_arities
  in
  (fun t continuation_arities -> { t with continuation_arities })
    t0 continuation_arities0

(** val record_continuation_arity : t -> Original_handlers.t -> t coq_M **)

let record_continuation_arity t0 handlers =
  (fun f__1 f__2 x__0 ->
    match (x__0 : Original_handlers.t) with
    | Original_handlers.Recursive
        { invariant_params = x__1;
          lifted_params = x__2;
          continuation_handlers = x__3;
          can_be_lifted = x__4
        } ->
      f__1 x__1 x__2 x__3 x__4
    | Original_handlers.Non_recursive x__1 -> f__2 x__1)
    (fun invariant_params _ continuation_handlers _ ->
      let invariant_arity = Bound_parameters.arity invariant_params in
      Continuation.Lmap.fold
        (fun cont0 handler0 cont_uses_env ->
          record_continuation cont_uses_env cont0
            (Flambda_arity.concat invariant_arity
               (Bound_parameters.arity handler0.One_recursive_handler.params)))
        continuation_handlers t0)
    (fun t1 ->
      let { Non_recursive_handler.cont = cont0;
            Non_recursive_handler.params = params0;
            Non_recursive_handler.lifted_params = _;
            Non_recursive_handler.handler = _;
            Non_recursive_handler.is_exn_handler = _;
            Non_recursive_handler.can_be_lifted = _;
            Non_recursive_handler.is_cold = _
          } =
        t1
      in
      record_continuation t0 cont0 (Bound_parameters.arity params0))
    handlers

(** val add_continuation_use : t -> Continuation.t -> Continuation_use_kind.t ->
    Apply_cont_rewrite_id.t -> Downwards_env.t -> Flambda2_types.t list -> t
    coq_M **)

let add_continuation_use t0 cont0 kind id env_at_use arg_types =
  let arity =
    match Continuation.Map.find_opt cont0 t0.continuation_arities with
    | Some arity -> arity
    | None ->
      Misc.fatal_errorf
        "[CUE.add_continuation_use]: Continuation %a not found in \
         continuation_uses_env %a"
        Continuation.print cont0 print t0
  in
  let arg_types0, env_at_use0 =
    let tenv = Downwards_env.typing_env env_at_use in
    let machine_width = Flambda2_types.Typing_env.machine_width tenv in
    let tenv0, arg_types0 =
      Misc.Stdlib.List.fold_left_map2
        (fun tenv0 arg_type kind0 ->
          let kind_ty =
            (fun x__1 x__2 x__3 ->
              Flambda2_types.unknown_with_subkind ?alloc_mode:x__1 x__2 x__3)
              None machine_width kind0
          in
          match Flambda2_types.meet tenv0 arg_type kind_ty with
          | Or_bottom.Ok p ->
            let arg_type0, env = p in
            env, arg_type0
          | Or_bottom.Bottom -> tenv0, arg_type)
        tenv arg_types
        (Flambda_arity.unarized_components arity)
    in
    arg_types0, Downwards_env.with_typing_env env_at_use tenv0
  in
  let use = One_continuation_use.create kind env_at_use0 id arg_types0 in
  let continuation_uses0 =
    Continuation.Map.update cont0
      (fun o ->
        match o with
        | Some uses -> Some (Continuation_uses.add_use uses use)
        | None ->
          let uses = Continuation_uses.create cont0 arity in
          Some (Continuation_uses.add_use uses use))
      t0.continuation_uses
  in
  (fun t continuation_uses -> { t with continuation_uses })
    t0 continuation_uses0

(** val record_continuation_use : t -> Continuation.t -> Continuation_use_kind.t
    -> Downwards_env.t -> Flambda2_types.t list -> (t * Apply_cont_rewrite_id.t)
    coq_M **)

let record_continuation_use t0 cont0 kind env_at_use arg_types =
  let id = Apply_cont_rewrite_id.create () in
  let t1 = add_continuation_use t0 cont0 kind id env_at_use arg_types in
  t1, id

(** val get_typing_env_no_more_than_one_use : t -> Continuation.t ->
    Flambda2_types.Typing_env.t option coq_M **)

let get_typing_env_no_more_than_one_use t0 k =
  match Continuation.Map.find_or_null k t0.continuation_uses with
  | Or_null.Null -> None
  | Or_null.This cont_uses ->
    Continuation_uses.get_typing_env_no_more_than_one_use cont_uses

(** val get_continuation_uses : t -> Continuation.t -> Continuation_uses.t
    option coq_M **)

let get_continuation_uses t0 cont0 =
  Continuation.Map.find_opt cont0 t0.continuation_uses

(** val num_continuation_uses : t -> Continuation.t -> int coq_M **)

let num_continuation_uses t0 cont0 =
  match Continuation.Map.find_or_null cont0 t0.continuation_uses with
  | Or_null.Null -> 0
  | Or_null.This uses -> Continuation_uses.number_of_uses uses

(** val all_continuations_used : t -> Continuation.Set.t coq_M **)

let all_continuations_used t0 = Continuation.Map.keys t0.continuation_uses

(** val union : t -> t -> t coq_M **)

let union t1 t2 =
  let continuation_arities0 =
    Continuation.Map.union_total_shared
      (fun cont0 arity1 arity2 ->
        if arity1 == arity2
        then arity1
        else
          Misc.fatal_errorf "Continuation %a was declared several times"
            Continuation.print cont0)
      t1.continuation_arities t2.continuation_arities
  in
  let continuation_uses0 =
    Continuation.Map.union_total
      (fun _ -> Continuation_uses.union)
      t1.continuation_uses t2.continuation_uses
  in
  { continuation_uses = continuation_uses0;
    continuation_arities = continuation_arities0
  }

(** val remove : t -> Continuation.t -> t coq_M **)

let remove t0 cont0 =
  let continuation_arities0 =
    Continuation.Map.remove cont0 t0.continuation_arities
  in
  let continuation_uses0 = Continuation.Map.remove cont0 t0.continuation_uses in
  { continuation_uses = continuation_uses0;
    continuation_arities = continuation_arities0
  }

(** val delete_continuation_uses : t -> Continuation.t -> t coq_M **)

let delete_continuation_uses = remove

(** val clear_continuation_uses : t -> Continuation.t -> t coq_M **)

let clear_continuation_uses t0 cont0 =
  (fun t continuation_uses -> { t with continuation_uses })
    t0
    (Continuation.Map.update cont0
       (Option.map Continuation_uses.clear_uses)
       t0.continuation_uses)

(** val mark_non_inlinable : t -> t coq_M **)

let mark_non_inlinable t0 =
  let { continuation_uses = continuation_uses0;
        continuation_arities = continuation_arities0
      } =
    t0
  in
  let continuation_uses1 =
    Continuation.Map.map Continuation_uses.mark_non_inlinable continuation_uses0
  in
  { continuation_uses = continuation_uses1;
    continuation_arities = continuation_arities0
  }

(** val reset_uses : t -> t coq_M **)

let reset_uses t0 =
  let { continuation_uses = _; continuation_arities = continuation_arities0 } =
    t0
  in
  { continuation_uses = Continuation.Map.empty;
    continuation_arities = continuation_arities0
  }
